mapper.select:
SELECT CAST(gm.goods_id AS CHAR) AS id, CAST(gm.goods_id AS CHAR) AS couponId, gm.name AS name, gm.name AS couponName, COALESCE(NULLIF(gm.category_name, ''), '满减券') AS type, COALESCE(NULLIF(gm.category_name, ''), '满减券') AS typeName, FLOOR(COALESCE(gm.original_price_cent, 0) / 100) AS thresholdAmount, FLOOR(COALESCE(gm.selling_price_cent, 0) / 100) AS discountAmount, COALESCE(GROUP_CONCAT(DISTINCT rc.name ORDER BY rc.name SEPARATOR '、'), '部分房型可用') AS scopeText, COALESCE(gm.stock, 0) AS sendLimit, COALESCE(CAST(REGEXP_SUBSTR(COALESCE(gm.stock_mode, ''), '[0-9]+') AS UNSIGNED), 1) AS perUserLimit, COALESCE(NULLIF(gm.reservation_note, ''), '所有人可以领') AS receiveRuleText, CASE WHEN gm.shelf_status = 'on_shelf' THEN 1 ELSE 0 END AS shelfStatus, CASE WHEN gm.shelf_status = 'on_shelf' THEN 1 ELSE 0 END AS status, gm.created_at AS createdAt, gm.updated_at AS updatedAt FROM goods_main gm LEFT JOIN goods_room_category_rel grcr ON grcr.goods_id = gm.goods_id LEFT JOIN room_category rc ON rc.room_category_id = grcr.room_category_id WHERE gm.camp_id = #{campId} AND gm.goods_type = 'coupon' AND gm.is_deleted = 0
AND CASE WHEN gm.shelf_status = 'on_shelf' THEN 1 ELSE 0 END = #{shelfStatus}
GROUP BY gm.goods_id, gm.name, gm.category_name, gm.original_price_cent, gm.selling_price_cent, gm.stock, gm.stock_mode, gm.reservation_note, gm.shelf_status, gm.created_at, gm.updated_at ORDER BY gm.created_at DESC, gm.goods_id DESC
